"""Idempotently merge healthcare/pharma terms into Targets/Pharma/Resources/glossary_pharma.json.

Mirrors scripts/add_ai_terms.py — append-only, case-insensitive dedup against
existing terms, sort by (letter asc, term asc) on write. Each batch is a Python
list of entries built via the entry() helper, which enforces the category +
indication enums so we don't drift away from the lenses defined in
Sources/Industries/PharmaBrand.swift.

Voice (see docs/CLARITY_POLICY.md) — three tiers per entry:
  plain  — <=25 words, total novice, everyday metaphor, no new acronyms.
  snappy — ~18-30 words, informed generalist, italic accent.
  detail — 40-80 words, depth + a "where you'd hear it" beat. No link markup
           (the linker auto-wires any term that has its own entry).

The corpus is broadening from "JB Pharma" to "JB Healthcare": the biopharma
core plus payers/reimbursement, public health, digital health & health IT, and
care-delivery basics. New non-clinical clusters tag indication "General".

Usage:
    python scripts/add_pharma_terms.py
    python scripts/add_pharma_terms.py --batches 1,2     # run specific batches
    python scripts/add_pharma_terms.py --dry-run         # preview without writing
"""

from __future__ import annotations

import argparse
import json
from pathlib import Path

GLOSSARY = Path(__file__).parent.parent / "Targets" / "Pharma" / "Resources" / "glossary_pharma.json"

# Keep in sync with Sources/Industries/PharmaBrand.swift lenses and the
# CATEGORY_CLUSTERS["pharma"] partition in scripts/audit_hyperlinks.py.
VALID_CATEGORIES = {
    # Original biopharma set
    "Mechanism", "Clinical", "Regulatory", "Diagnostics",
    "Commercial / Market Access", "Manufacturing", "Pharmacovigilance",
    "Digital Health",
    # Healthcare broaden (2026-05)
    "Health Systems & Payers", "Public Health", "Care Delivery",
}

VALID_INDICATIONS = {
    "General", "Oncology", "Rare Disease", "Neurology", "Infectious Disease",
    "Immunology", "Women's Health", "Cardiovascular", "Gastroenterology",
    "Dermatology", "Metabolic", "Respiratory", "Mental Health", "Ophthalmology",
}


def entry(term, full, snappy, detail, sources, indications=None, category="Mechanism", plain=""):
    assert category in VALID_CATEGORIES, f"Unknown category '{category}' for term '{term}'"
    indications = indications or ["General"]
    for ind in indications:
        assert ind in VALID_INDICATIONS, f"Unknown indication '{ind}' for term '{term}'"
    return {
        "letter": term[0].upper(),
        "term": term,
        "full": full,
        "plain": plain,
        "snappy": snappy,
        "detail": detail,
        "indications": indications,
        "category": category,
        "sources": sources,
    }


