# ---------------------------------------------------------------------------
# Batch 5 — Health Systems & Payers. How US healthcare is paid for: the
# programs (Medicare, Medicaid), plan types (HMO, PPO), payment models
# (fee-for-service vs value-based), and cost-sharing (deductible, coinsurance).
# Links densely to the existing access cluster (PBM, Formulary, Prior
# Authorization, Copay, Step Therapy, Rebate, 340B) and to CMS/HRSA (Batch 4).
# Homonym-prone words avoided as bare terms: "Claims Data" not "Claim",
# "Health Plan" not "Plan", no bare "Premium/Network/Carrier".
# ---------------------------------------------------------------------------
BATCH_5 = [
    entry("Medicare", "",
          "The US federal health insurance program for people 65 and older (and some younger people with disabilities) — and the market's most powerful payer.",
          "Medicare covers ~65 million Americans across Part A (hospital), Part B (outpatient), Part C (Medicare Advantage), and Part D (drugs). Run by CMS, its coverage and payment rules — now including drug-price negotiation — set the tone for the whole system. You'll hear Medicare in every US reimbursement and drug-pricing discussion.",
          ["CMS Glossary"], indications=["General"], category="Health Systems & Payers",
          plain="The US government health insurance program for people 65 and older — and the single most powerful payer in the market."),
    entry("Medicaid", "",
          "The joint federal-state program covering low-income Americans — the largest single source of health coverage in the US.",
          "Medicaid is administered by states within federal rules and covers over 80 million people, including long-term care and a large share of births. Run with CMS oversight, its budgets and eligibility rules drive access for the poorest patients. You'll hear Medicaid in any coverage, safety-net, or 340B discussion.",
          ["CMS Glossary"], indications=["General"], category="Health Systems & Payers",
          plain="The joint federal-state program that covers low-income Americans — the largest single source of health coverage in the US."),
    entry("Medicare Advantage", "MA",
          "Privately run Medicare — insurers are paid a fixed amount to cover a member's care, the fast-growing alternative to traditional Medicare.",
          "Under Medicare Advantage (Part C), CMS pays a private insurer a capitated amount per enrollee to manage all their care, often with extra benefits and a network. It now covers more than half of Medicare beneficiaries. You'll hear Medicare Advantage in managed-care, risk-adjustment, and insurer-earnings discussion.",
          ["CMS Glossary"], indications=["General"], category="Health Systems & Payers",
          plain="The private-insurer version of Medicare, where a company is paid a set amount to cover all of a member's care."),
    entry("Medicare Part D", "Part D",
          "The Medicare prescription-drug benefit, delivered through private plans and their formularies.",
          "Part D covers outpatient prescription drugs via private plans, each with its own formulary and cost-sharing, negotiated through PBMs. The Inflation Reduction Act capped out-of-pocket costs and launched Medicare price negotiation here. You'll hear Part D in every drug-pricing and formulary-access discussion.",
          ["CMS Glossary"], indications=["General"], category="Health Systems & Payers",
          plain="The part of Medicare that pays for prescription drugs, run through private plans with their own covered-drug lists."),
    entry("Managed Care", "",
          "The dominant US model where an insurer actively steers cost and care through networks, prior authorization, and incentives — not just paying bills.",
          "Managed care organizations (HMOs, PPOs, Medicare Advantage) use provider networks, utilization management, and payment incentives to control spending. It replaced passive fee-for-service indemnity insurance. You'll hear managed care behind every formulary, prior authorization, and network-design decision.",
          ["CMS Glossary"], indications=["General"], category="Health Systems & Payers",
          plain="The dominant US insurance model where the insurer actively steers your care and costs, rather than just paying the bills."),
    entry("HMO", "Health Maintenance Organization",
          "A managed-care plan that's cheaper but stricter — you pick a primary care doctor and need referrals to see specialists, all within a set network.",
          "An HMO keeps premiums low by requiring care within its network and routing access through a primary care gatekeeper, with little out-of-network coverage. You'll hear HMO contrasted with the looser PPO whenever plan design or managed care comes up.",
          ["CMS Glossary"], indications=["General"], category="Health Systems & Payers",
          plain="A cheaper but stricter insurance plan: you pick a main doctor, need referrals for specialists, and must stay in its network."),
    entry("PPO", "Preferred Provider Organization",
          "A managed-care plan that costs more but offers flexibility — see specialists without referrals and go out-of-network for a higher share of the cost.",
          "A PPO lets members see any provider, paying less for in-network 'preferred' ones, with no gatekeeper referrals. The trade-off versus an HMO is higher premiums for more freedom. You'll hear PPO in any plan-design or benefits discussion.",
          ["CMS Glossary"], indications=["General"], category="Health Systems & Payers",
          plain="A more flexible, pricier insurance plan: see specialists without referrals and go outside the network for a higher cost."),
    entry("Fee-for-Service", "FFS",
          "Paying providers for each test, visit, or procedure — the traditional model critics blame for rewarding volume over health.",
          "Under fee-for-service, every service generates a separate payment, which can incentivize more care rather than better outcomes. It's the baseline that value-based care models — ACOs, bundled payments, capitation — are designed to replace. You'll hear FFS as the foil in any payment-reform discussion.",
          ["CMS Glossary"], indications=["General"], category="Health Systems & Payers",
          plain="Paying a doctor or hospital for each separate test or procedure — the old model critics say rewards doing more, not doing better."),
    entry("Value-Based Care", "VBC",
          "Paying for health outcomes rather than the volume of services — the umbrella reform meant to replace fee-for-service.",
          "Value-based care ties provider payment to quality and total cost through models like ACOs, bundled payments, and capitation, shifting financial risk onto providers to reward keeping people healthy. You'll hear VBC across CMS demonstrations and payer-strategy discussion.",
          ["CMS Glossary"], indications=["General"], category="Health Systems & Payers",
          plain="Paying doctors and hospitals for keeping patients healthy and outcomes good, instead of for the sheer number of services they provide."),
    entry("Capitation", "",
          "Paying a provider a fixed amount per patient per month to cover all their care — flipping the incentive from volume to efficiency.",
          "Under capitation a provider receives a set per-member-per-month payment regardless of services used, bearing the financial risk if care costs more. It underpins many HMOs and value-based-care arrangements. You'll hear capitation in managed-care and risk-sharing discussion.",
          ["CMS Glossary"], indications=["General"], category="Health Systems & Payers",
          plain="Paying a doctor a fixed monthly amount per patient to cover all their care — so the incentive shifts from volume to efficiency."),
    entry("Bundled Payment", "Episode-Based Payment",
          "A single payment covering everything involved in one episode of care — say a hip replacement — instead of paying each provider separately.",
          "A bundled payment pays one lump sum for an entire care episode (surgery plus hospital stay plus rehab), making providers split a fixed budget and coordinate. It's a core value-based-care model alongside ACOs. You'll hear bundled payment in surgical and CMS payment-reform discussion.",
          ["CMS Glossary"], indications=["General"], category="Health Systems & Payers",
          plain="One payment that covers everything for a single treatment episode — like a knee replacement — instead of paying each provider on its own."),
    entry("ACO", "Accountable Care Organization",
          "A group of providers who share responsibility — and the savings or losses — for the total cost and quality of a patient population's care.",
          "An ACO is a network of doctors and hospitals jointly accountable for a defined population; if they keep spending below a benchmark while hitting quality targets, they share the savings. A flagship Medicare value-based-care model. You'll hear ACO in any payment-reform or population-health discussion.",
          ["CMS Glossary"], indications=["General"], category="Health Systems & Payers",
          plain="A group of doctors and hospitals that together take responsibility for the cost and quality of a group of patients' care."),
    entry("DRG", "Diagnosis-Related Group",
          "The classification that pays a hospital a fixed amount per admission based on the diagnosis — not on how many days or services it racks up.",
          "Medicare pays inpatient stays by DRG: each admission is grouped by diagnosis and procedure into a category with a set payment, so hospitals profit by being efficient. It reshaped hospital economics when introduced in the 1980s. You'll hear DRG in any hospital-reimbursement discussion.",
          ["CMS Glossary"], indications=["General"], category="Health Systems & Payers",
          plain="The system that pays a hospital a flat amount for an admission based on the diagnosis, rather than per day or per service."),
    entry("Deductible", "",
          "The amount you pay out of pocket each year before your insurance starts paying.",
          "A deductible is the annual threshold a patient must cover before the plan contributes; high-deductible plans trade lower premiums for more upfront cost. After it's met, coinsurance and copays apply up to the out-of-pocket maximum. You'll hear deductible in any benefit-design or patient-affordability discussion.",
          ["CMS Glossary"], indications=["General"], category="Health Systems & Payers",
          plain="The amount you pay out of your own pocket each year before your insurance starts chipping in."),
    entry("Coinsurance", "",
          "Your share of a medical bill expressed as a percentage — say 20% — that you keep paying after meeting your deductible.",
          "Coinsurance is percentage-based cost-sharing (e.g., the plan pays 80%, you pay 20%) that kicks in after the deductible and continues until the out-of-pocket maximum. It differs from a flat copay. You'll hear coinsurance in benefit-design and specialty-drug affordability discussion.",
          ["CMS Glossary"], indications=["General"], category="Health Systems & Payers",
          plain="Your share of a medical bill as a percentage — like 20% — that you pay after meeting your deductible."),
    entry("Out-of-Pocket Maximum", "OOP Max",
          "The yearly cap on what you can be forced to pay; once you hit it, insurance covers 100% of covered care.",
          "The out-of-pocket maximum limits a patient's total annual cost-sharing — deductible plus copays plus coinsurance — after which the plan pays everything for covered services. It's the backstop that makes catastrophic illness survivable financially. You'll hear it in benefit-design and affordability discussion.",
          ["CMS Glossary"], indications=["General"], category="Health Systems & Payers",
          plain="The yearly limit on what you can be made to pay; once you reach it, insurance covers the rest of your covered care."),
    entry("Utilization Management", "UM",
          "The insurer toolkit — prior authorization, step therapy, quantity limits — for controlling which services and drugs get paid for.",
          "Utilization management reviews care for medical necessity and cost before or during treatment, using prior authorization, step therapy, and concurrent review. It's the friction patients and providers feel most, and a perennial reform target. You'll hear UM behind every access-and-coverage complaint.",
          ["CMS Glossary"], indications=["General"], category="Health Systems & Payers",
          plain="The insurer's toolkit — prior approvals, 'try this cheaper drug first' rules, limits — for controlling what care gets paid for."),
    entry("Pharmacy Benefit Manager", "PBM",
          "The middlemen who run drug benefits for insurers — negotiating rebates, building formularies, and steering which drugs you can get and what they cost.",
          "PBMs sit between drugmakers, insurers, and pharmacies, negotiating rebates in exchange for formulary placement and processing prescription claims. The big three control most of the market, and their opaque economics draw constant scrutiny. You'll hear pharmacy benefit manager in every drug-pricing and gross-to-net discussion.",
          ["CMS Glossary"], indications=["General"], category="Health Systems & Payers",
          plain="The middlemen who run drug coverage for insurers — negotiating discounts and deciding which medicines you can get and at what cost."),
    entry("Specialty Pharmacy", "",
          "A pharmacy built to handle complex, high-cost drugs — biologics, cancer and rare-disease therapies — that need special handling and support.",
          "Specialty pharmacies dispense expensive, often injectable or refrigerated drugs requiring patient education, adherence support, and prior authorization. They're where most of pharma's revenue growth flows and a focus of PBM consolidation. You'll hear specialty pharmacy in any biologics or market-access discussion.",
          ["CMS Glossary"], indications=["General"], category="Health Systems & Payers",
          plain="A pharmacy set up to handle complex, very expensive drugs — like biologics and cancer treatments — that need special care and support."),
    entry("Claims Data", "Administrative Data",
          "The billing records insurers generate for every paid service — a vast real-world dataset researchers mine for how medicine is actually used.",
          "Because every reimbursed visit, test, and prescription creates a claim, claims data offers population-scale evidence on utilization, outcomes, and cost — a backbone of health economics and real-world evidence, despite gaps versus the clinical record. You'll hear claims data in HEOR and outcomes-research discussion.",
          ["ISPOR"], indications=["General"], category="Health Systems & Payers",
          plain="The billing records insurers create for every paid service — a huge real-world dataset researchers use to study how medicine is really used."),
    entry("Medical Loss Ratio", "MLR",
          "The share of insurance premiums an insurer must spend on actual care rather than profit and overhead — capped by law.",
          "The Affordable Care Act requires insurers to spend at least 80-85% of premiums on medical care and quality (the medical loss ratio) or rebate the difference, limiting how much can go to administration and profit. You'll hear MLR in insurer-earnings and health-policy discussion.",
          ["CMS Glossary"], indications=["General"], category="Health Systems & Payers",
          plain="The share of your insurance premiums that, by law, must go to actual medical care rather than the insurer's profit and overhead."),
]


# ---------------------------------------------------------------------------
# Batch 6 — Public Health & epidemiology. The vocabulary of populations rather
# than patients: how disease is counted (incidence/prevalence, morbidity/
# mortality), how it spreads and is named (outbreak -> epidemic -> pandemic,
# endemic, R0, herd immunity), how it's watched and contained (surveillance,
# notifiable disease, contact tracing, quarantine), and how it's studied
# (cohort vs case-control, confounding). Tightly self-referential, and links
# out to CDC/WHO (Batch 4) and the existing Vaccine entry.
# Homonym traps dodged: "Disease Vector" not "Vector" (gene-therapy sense),
# "Disease Surveillance" not "Surveillance" (pharmacovigilance sense).
# ---------------------------------------------------------------------------
BATCH_6 = [
    entry("Incidence", "",
          "The rate of *new* cases of a disease in a population over a period — the flow, versus the standing pool that prevalence measures.",
          "This rate counts how many people develop a condition during a window — say, new flu cases per week. It captures risk and the speed of spread, which is why outbreak investigators and Disease Surveillance teams watch it. Distinguish it from prevalence, the total existing cases: a fast-killing or fast-curing disease can run high here but low there. You'll see these rates in every CDC field report.",
          ["CDC"], indications=["General"], category="Public Health",
          plain="How many people newly catch a disease in a given time. It measures how fast something is spreading, not how many already have it."),
    entry("Prevalence", "",
          "The share of a population that *has* a condition at a given moment — the standing pool, counting old and new cases alike, unlike incidence.",
          "A snapshot: what fraction of people live with diabetes today, regardless of when they were diagnosed. It reflects both how often a disease arises — its incidence — and how long people live with it, so chronic conditions show high figures. The number drives budgeting and public-health planning, and pairs with morbidity to size total burden. Reporters quote it when they say '1 in 10 adults has...'; the CDC publishes it for major chronic diseases.",
          ["CDC"], indications=["General"], category="Public Health",
          plain="Out of everyone in a group, the portion who have a disease right now — counting both new and long-standing cases."),
    entry("Morbidity", "",
          "The burden of *illness* in a population — how much disease, disability, and ill-health there is, as distinct from mortality, which counts deaths.",
          "This captures sickness rather than death: cases, complications, disability, and reduced quality of life. Agencies pair it with mortality to size a disease's total toll — the CDC's flagship bulletin is literally the Morbidity and Mortality Weekly Report. Chronic conditions with high prevalence drive most of it even when they rarely kill. You'll hear 'morbidity and mortality' as a fixed phrase at any health-policy briefing.",
          ["CDC"], indications=["General"], category="Public Health",
          plain="How much disease and ill-health there is in a group of people — sickness and disability, separate from how many die."),
    entry("Mortality", "",
          "The rate of *death* in a population — overall or from a specific cause — the grim companion to morbidity in every public-health tally.",
          "It measures deaths, usually per 100,000 people a year, all-cause or disease-specific. Epidemiologists read it alongside morbidity to judge how dangerous a condition is, while the case fatality rate narrows the lens to deaths among those who fall ill. Excess deaths above the expected baseline became a headline metric during the pandemic. The CDC and WHO publish death rates for every country.",
          ["CDC", "WHO"], indications=["General"], category="Public Health",
          plain="How many people in a group die in a given time, often from a specific cause. The basic measure of how deadly something is."),
    entry("Epidemic", "",
          "A sudden surge of a disease *above* its normal level in a region — bigger than an outbreak, more contained than a pandemic.",
          "Cases climb well beyond what's expected for a place and time. It sits on a spectrum: a localized outbreak can grow into one, and when it crosses continents it becomes a pandemic. Whether it ignites depends partly on the Basic Reproduction Number and the population's herd immunity; a disease that never surges this way is instead called endemic. The CDC and WHO declare and track them.",
          ["CDC", "WHO"], indications=["General"], category="Public Health",
          plain="A disease spreading through a community much faster or wider than usual. Bigger than a local outbreak, but not yet worldwide."),
    entry("Pandemic", "",
          "An *epidemic gone global* — a disease spreading across many countries or continents at once, as COVID-19 and influenza have done.",
          "An epidemic that has crossed international borders on a large scale, hitting whole regions of the world at once; the WHO formally declares them. These events strain disease surveillance, vaccine supply, and herd immunity all at the same time, and their toll is counted in excess mortality. After a pathogen settles into steady circulation, the crisis phase can fade toward an endemic equilibrium rather than vanishing.",
          ["WHO"], indications=["General"], category="Public Health",
          plain="An epidemic that has spread across many countries or the whole world at the same time, like COVID-19."),
    entry("Endemic", "",
          "A disease *constantly present* at a baseline level in an area — always smoldering, like malaria in the tropics, rather than surging or vanishing.",
          "Describes a disease that circulates steadily without dying out or exploding. Malaria is endemic to much of the tropics; chickenpox was before vaccines. A disease can shift between states — an epidemic or pandemic may settle into this kind of steady equilibrium once enough herd immunity builds. Public-health teams work to push these baseline levels down through immunization and disease surveillance.",
          ["WHO"], indications=["General"], category="Public Health",
          plain="A disease that is always around at a steady, low level in a place — never gone, but not exploding either."),
    entry("Outbreak", "",
          "A *sudden, localized* cluster of cases above the norm — the smallest fire, which contact tracing can contain before it grows into an epidemic.",
          "A sharp, often local rise in cases above normal — a foodborne cluster, a measles flare in an under-vaccinated school. Caught early, contact tracing and quarantine can snuff it out before it becomes an epidemic. These events trigger disease surveillance and, for notifiable diseases, mandatory reporting to the CDC. The line between a large one and an epidemic is mostly a matter of scale.",
          ["CDC"], indications=["General"], category="Public Health",
          plain="A sudden jump in cases of a disease in one place or group. The earliest, most local stage before it can grow into an epidemic."),
    entry("Basic Reproduction Number", "R₀ (R-nought)",
          "*R₀* — the average number of people one infected person passes a disease to in a fully susceptible population. Above 1 it spreads; below 1 it fades.",
          "Written R₀ and said 'R-nought,' it is contagion's headline statistic: measles sits near 15, seasonal flu near 1.3. It sets the herd immunity threshold — the share who must be immune to halt spread — and predicts whether an outbreak grows into an epidemic. Teams also track a real-time cousin, the effective reproduction number, to judge whether control measures are working.",
          ["CDC"], indications=["General"], category="Public Health",
          plain="How many people, on average, one sick person infects when no one is immune. Above one means it spreads; below one means it dies out."),
    entry("Herd Immunity", "",
          "The point where *enough* of a population is immune that a disease can't find new hosts — shielding even those who aren't immune themselves.",
          "Also called community immunity, it kicks in once immune people — through vaccines or past infection — are dense enough to break chains of transmission. The threshold rises with the Basic Reproduction Number: highly contagious measles needs ~95% coverage. Immunization programs target it explicitly, which is why vaccine hesitancy can let an endemic disease flare into an outbreak. It guards infants and the immunocompromised who can't be vaccinated.",
          ["CDC"], indications=["General"], category="Public Health",
          plain="When so many people are immune to a disease that it can't spread easily, which protects even the few who aren't immune."),
    entry("Disease Vector", "",
          "A living carrier — usually a *mosquito, tick, or flea* — that ferries a pathogen between hosts, as mosquitoes do for malaria.",
          "An organism that transmits a pathogen between hosts without necessarily falling ill itself. Mosquitoes (malaria, dengue, Zika), ticks (Lyme), and fleas (plague) are the classics. Many vector-borne diseases are a kind of zoonosis, jumping from animals to people, and climate change is widening their range — a growing worry for outbreak preparedness and disease surveillance.",
          ["WHO"], indications=["General"], category="Public Health",
          plain="A creature like a mosquito or tick that carries a disease from one person or animal to another without usually getting sick itself."),
    entry("Zoonosis", "",
          "A disease that *jumps from animals to humans* — rabies, COVID-19, and Ebola all crossed the species barrier this way.",
          "An infection that spills over from animals to people, sometimes via a disease vector like a mosquito, sometimes by direct contact. Most new human pathogens — including the coronaviruses behind recent epidemics — arrive this way. Watching wildlife and livestock is a frontline defense, since spillover is where many an outbreak and the occasional pandemic begins. The 'One Health' approach links animal, human, and environmental disease surveillance.",
          ["WHO"], indications=["General"], category="Public Health",
          plain="A disease that spreads from animals to humans, like rabies or COVID-19. Many brand-new human diseases start this way."),
    entry("Disease Surveillance", "",
          "The continuous *watch* for disease in a population — collecting case data so outbreaks are spotted and stopped before they spread.",
          "The ongoing collection and analysis of health data — lab reports, doctor visits, death records — to detect threats and guide response. Notifiable diseases must by law be reported into it. It's how the CDC and WHO spot an outbreak before it becomes an epidemic, follow incidence trends, and target immunization. Modern systems fold in wastewater, pharmacy sales, and search queries for faster signals.",
          ["CDC", "WHO"], indications=["General"], category="Public Health",
          plain="Constantly tracking who is getting sick across a population, so health officials can catch and stop outbreaks early."),
    entry("Notifiable Disease", "",
          "A condition doctors and labs are *legally required to report* to health authorities — the raw feed for disease surveillance.",
          "Must by law be reported to public-health authorities on diagnosis — measles, tuberculosis, certain STIs, novel pathogens. The mandatory flow feeds disease surveillance and lets agencies launch contact tracing or quarantine fast. Each US state sets its own list; the CDC aggregates nationally while the WHO runs international reporting for events of global concern. It is the legal backbone of outbreak detection.",
          ["CDC"], indications=["General"], category="Public Health",
          plain="A disease that doctors must legally report to health officials whenever they diagnose it, so authorities can track and respond to it."),
    entry("Social Determinants of Health", "SDOH",
          "The *non-medical* conditions — income, housing, education, food, neighborhood — that shape health long before any clinic visit does.",
          "The circumstances people are born, live, and work in: economic standing, education, food security, housing, and access to care. They explain much of the gap in morbidity and mortality between populations — often more than medical care itself. Payers and value-based care programs increasingly screen for them, since fixing housing or nutrition can cut costly hospital use. You'll hear the term at every health-equity discussion.",
          ["CDC"], indications=["General"], category="Public Health",
          plain="The everyday conditions — money, housing, schooling, food, neighborhood — that affect your health more than doctors and medicine do."),
    entry("Screening", "",
          "Testing *apparently healthy* people to catch disease early — mammograms, colonoscopies, newborn blood spots — before symptoms appear.",
          "Looking for disease in people without symptoms, to catch it when treatment works best — cancer (mammography, colonoscopy, Pap), newborn metabolic panels, blood-pressure checks. A good program weighs a test's sensitivity and specificity against the harms of false alarms and overdiagnosis. Population programs can lower mortality, but only where early action helps, by shifting detected incidence toward earlier stages — and are most worthwhile where prevalence is high enough to justify mass testing. Coverage rules often hinge on task-force recommendations.",
          ["NIH MedlinePlus"], indications=["General"], category="Public Health",
          plain="Testing people who feel fine to catch a disease early, like mammograms or colonoscopies, when it's easier to treat."),
    entry("Cohort Study", "",
          "An observational study that *follows a group forward in time*, comparing disease rates in the exposed and unexposed — epidemiology's workhorse.",
          "Tracks a defined group into the future, watching who develops disease based on exposures like smoking or a drug. Because it measures incidence directly, it can compute relative risk — but it's slow and costly for rare outcomes, and must adjust for confounding. Contrast the case-control study, which works backward from disease. Landmark cohorts like Framingham shaped what we know about cardiovascular risk; it ranks below the randomized controlled trial in evidence.",
          ["NIH"], indications=["General"], category="Public Health",
          plain="A study that follows a group of people over time to see who gets sick, comparing those exposed to something with those who weren't."),
    entry("Case-Control Study", "",
          "An observational study that starts *with the sick*, then looks backward for their exposures — fast and cheap for rare diseases.",
          "Compares people who have a disease (cases) with similar people who don't (controls), looking back for differences in exposure. It's efficient for rare conditions where a cohort study would take decades, but prone to recall bias and confounding, and it gives odds ratios rather than direct risk. It helped tie smoking to lung cancer, and is a staple of epidemiology and pharmacovigilance signal work.",
          ["NIH"], indications=["General"], category="Public Health",
          plain="A study that starts with people who already have a disease and looks back to find what might have caused it, versus people who don't."),
    entry("Confounding", "",
          "When a *hidden third factor* distorts an apparent link between cause and effect — the bane of every observational study.",
          "Happens when a variable tied to both the exposure and the outcome creates a misleading association — coffee seems to 'cause' cancer until you notice coffee drinkers smoked more. The intruder masquerades as a cause. A cohort study or case-control study fights it with matching and statistical adjustment; the randomized controlled trial defeats it by design, which is why it outranks them in evidence. Spotting it is core to reading any epidemiology paper.",
          ["NIH"], indications=["General"], category="Public Health",
          plain="When a hidden factor fools you into thinking one thing causes another. Like blaming coffee for a disease that's really caused by smoking."),
    entry("Case Fatality Rate", "CFR",
          "The share of *diagnosed cases* who die of a disease — how lethal it is once caught, distinct from population mortality.",
          "Deaths divided by confirmed cases — Ebola's can top 50%, seasonal flu's stays well under 1%. It gauges severity but is slippery early in an outbreak, when uncounted mild cases make it look scarier than it is. Don't confuse it with the infection fatality rate, which counts everyone infected including the undiagnosed, or with overall mortality. Reported constantly during any epidemic.",
          ["CDC"], indications=["General"], category="Public Health",
          plain="Out of everyone diagnosed with a disease, the percentage who die from it. A measure of how deadly it is once you catch it."),
    entry("Immunization", "",
          "The process of making someone *immune* to a disease — usually via a vaccine — and the programs built to deliver them at scale.",
          "How a person becomes protected against an infection, most often by a vaccine that trains the immune system without causing illness. National schedules and campaigns aim to reach the herd immunity threshold that shields whole communities. Coverage gaps — from access barriers or vaccine hesitancy — let preventable diseases like measles resurge. The WHO and CDC set and monitor schedules; it's among the highest-return moves in public health.",
          ["WHO", "CDC"], indications=["General"], category="Public Health",
          plain="Making someone protected against a disease, usually with a vaccine. Also the programs that get shots to whole populations."),
    entry("Vaccine Hesitancy", "",
          "*Reluctance or refusal* to vaccinate despite available shots — the WHO names it among the top threats to global health.",
          "Delay or refusal of vaccines driven by mistrust, misinformation, complacency, or access barriers. When it pushes coverage below the herd immunity threshold, diseases like measles come roaring back, undercutting the whole point of an immunization program. The WHO listed it among the top-ten global health threats. Communicators counter it with trusted messengers rather than data dumps — a recurring theme at any disease surveillance and health-policy discussion.",
          ["WHO"], indications=["General"], category="Public Health",
          plain="When people delay or refuse vaccines even though they're available, often due to fear or misinformation. It lets old diseases return."),
    entry("Contact Tracing", "",
          "Finding everyone an infected person *may have exposed*, then alerting or isolating them — shoe-leather epidemiology that breaks transmission chains.",
          "Identifies, notifies, and monitors the people a confirmed case has been near, so they can quarantine or get tested before infecting others. A frontline tool against any outbreak — central to controlling TB, STIs, Ebola, and COVID-19. Paired with disease surveillance and rapid testing, it can hold an epidemic's reproduction number below one. Effectiveness collapses once cases outpace the tracers, as happened during the pandemic.",
          ["CDC"], indications=["General"], category="Public Health",
          plain="Tracking down everyone a sick person may have exposed, then warning them, so they can stay home before spreading the disease further."),
    entry("Quarantine", "",
          "*Separating and restricting* people who may have been exposed to a contagious disease — distinct from isolating those already confirmed sick.",
          "Keeps apart people who were exposed to a contagious disease but aren't yet known to be infected, during the incubation period; isolation, by contrast, separates the confirmed sick. The word traces to the 40-day ('quaranta') ship holds of plague-era Venice. Paired with contact tracing, it helps choke off an outbreak. Authorities hold legal quarantine powers for notifiable diseases, balanced against civil liberties.",
          ["CDC"], indications=["General"], category="Public Health",
          plain="Keeping people who might have caught a contagious disease away from others for a while, in case they become sick and spread it."),
]


# ---------------------------------------------------------------------------
# Batch 7 — Digital Health & Health IT. How healthcare is digitized and
# connected: the record systems (EHR/EMR), the standards that connect them
# (HL7, FHIR, interoperability, HIE), care at a distance (telehealth,
# telemedicine, RPM), the regulated-software frontier (SaMD, CDS), privacy
# (HIPAA, PHI), and the data/trial modernization layer (RWD, decentralized
# trials, ePRO, digital biomarkers, wearables). Links to the existing DTx and
# Real-World Evidence entries, plus FDA (Batch 4) and Claims Data (Batch 5).
# Note: acronym-only terms (HL7, FHIR, HIPAA, ePRO) link by name; spelled-out
# terms (Electronic Health Record...) are referenced in full where a link is
# wanted, since the linker matches the term string, not its `full` acronym.
# ---------------------------------------------------------------------------
BATCH_7 = [
    entry("Electronic Health Record", "EHR",
          "A patient's *digital chart* — meds, labs, diagnoses, notes — built to follow them across every clinician and setting, unlike a single practice's records.",
          "The longitudinal digital record of a patient's health, built to be shared across providers — the backbone of modern care and a prerequisite for interoperability. Vendors like Epic and Cerner dominate US hospitals. These systems feed clinical decision support, patient portals, and real-world evidence, though clinician burnout from clunky interfaces is a chronic complaint. Distinguish it from the narrower electronic medical record, confined to one practice.",
          ["ONC"], indications=["General"], category="Digital Health",
          plain="The digital version of a patient's chart — diagnoses, medications, test results — shared across the clinicians who treat them."),
    entry("Electronic Medical Record", "EMR",
          "A *single practice's* digital chart — the narrower, older cousin of the electronic health record, which is built to travel between providers.",
          "An EMR digitizes the records of one practice or hospital — diagnoses, treatments, history — but isn't designed to move between organizations. The terms are often used interchangeably, though strictly the electronic health record is the broader, shareable version enabling interoperability and health information exchange. The distinction matters in health-IT policy and procurement.",
          ["ONC"], indications=["General"], category="Digital Health",
          plain="A digital chart within a single doctor's office or hospital — like a paper record gone electronic, but not easily shared elsewhere."),
    entry("Interoperability", "",
          "Whether health IT systems can *exchange and use* each other's data — the long-sought goal that lets records follow the patient.",
          "The capacity of electronic health record systems and devices to exchange data and make it usable — not merely transmit it. It underpins health information exchange and is the reason standards like HL7 and FHIR exist. US rules now ban 'information blocking' to force it. Without it, data sits in silos; with it, clinical decision support and real-world evidence grow far richer.",
          ["ONC"], indications=["General"], category="Digital Health",
          plain="The ability of different health computer systems to share and actually use each other's data — so your records aren't trapped in one office."),
    entry("HL7", "Health Level Seven",
          "The *messaging-standards* body whose formats let health IT systems talk — the older foundation beneath the newer FHIR.",
          "Health Level Seven sets the messaging standards that move data between health IT systems — lab results, admissions, orders. Its older 'v2' messages are still everywhere in hospitals, while its modern, web-friendly successor FHIR is taking over new work. Both serve interoperability. You'll hear HL7 whenever integration engineers and electronic health record vendors discuss connecting systems.",
          ["ONC"], indications=["General"], category="Digital Health",
          plain="A long-standing set of standards for how health computer systems format and swap messages, so they can understand each other."),
    entry("FHIR", "Fast Healthcare Interoperability Resources",
          "The *modern, app-friendly* standard (said 'fire') for exchanging health data — HL7's web-era successor, now mandated for US patient-data access.",
          "Pronounced 'fire,' it is HL7's modern standard: it uses ordinary web APIs to share discrete data elements, making it far easier for apps to plug into an electronic health record. US regulations require FHIR-based patient-access APIs, accelerating interoperability. It's why a phone app can now pull your lab results — a staple of every health-IT integration discussion.",
          ["ONC"], indications=["General"], category="Digital Health",
          plain="A modern web-based standard that makes it much easier for health apps and systems to share specific pieces of data on demand."),
    entry("Health Information Exchange", "HIE",
          "The *electronic sharing* of patient records across organizations — both the act and the regional networks that broker it.",
          "It lets unaffiliated providers share records, so an emergency room can pull your history from another system. It depends on interoperability and standards like FHIR, and runs through regional or state networks. Done well, it cuts duplicate testing and medication errors. You'll hear HIE in health-IT policy and care-coordination talk, alongside the electronic health record systems it connects.",
          ["ONC"], indications=["General"], category="Digital Health",
          plain="Sharing patient records electronically between different hospitals and clinics, so providers can see care you received elsewhere."),
    entry("Telehealth", "",
          "*Remote* delivery of health services — video visits, messaging, home monitoring — the broad umbrella over the narrower telemedicine.",
          "Covers the full range of care delivered at a distance: video visits, secure messaging, remote patient monitoring, and clinician-to-clinician consults. It exploded during the pandemic when payers and Medicare temporarily relaxed coverage rules. Broader than telemedicine, which means specifically clinical care. You'll hear telehealth in access, rural-care, and reimbursement discussion, since coverage parity remains a live policy fight.",
          ["HRSA"], indications=["General"], category="Digital Health",
          plain="Getting care from a doctor remotely — by video, phone, or app — instead of traveling to an office."),
    entry("Telemedicine", "",
          "*Clinical care at a distance* — diagnosis and treatment by video or phone — the medical core within the wider telehealth umbrella.",
          "The remote practice of clinical medicine — a video consult, a teledermatology photo review, a tele-stroke assessment guiding emergency treatment. It's the clinical subset of telehealth, which also spans non-clinical services. Reimbursement and cross-state licensing are the perennial hurdles. You'll hear telemedicine wherever access gaps, rural health, or remote patient monitoring and wearable devices come up.",
          ["HRSA"], indications=["General"], category="Digital Health",
          plain="Seeing a doctor for diagnosis or treatment over video or phone, rather than in person."),
    entry("Remote Patient Monitoring", "RPM",
          "Home *connected devices* streaming a patient's vitals to clinicians between visits — a pillar of telehealth for chronic-disease care.",
          "It uses connected devices — blood-pressure cuffs, glucose meters, pulse oximeters, wearables — to capture health data at home and route it to clinicians. It extends telehealth into continuous care, helping manage chronic conditions and catch deterioration early. Medicare now reimburses it with dedicated codes. You'll hear RPM alongside wearable sensors and digital biomarkers in connected-health discussion.",
          ["HRSA"], indications=["General"], category="Digital Health",
          plain="Using connected devices at home — like blood-pressure cuffs or glucose monitors — to send your health data to your care team between visits."),
    entry("Software as a Medical Device", "SaMD",
          "*Software that is itself the medical device* — diagnosing or treating without hardware — and is regulated by the FDA as such.",
          "It performs a medical function on its own — an algorithm flagging strokes on a CT scan, an app detecting arrhythmia — rather than running a physical instrument. The FDA regulates it, with evolving pathways for AI models that keep learning. It overlaps with digital therapeutics (DTx). You'll hear SaMD wherever health AI, regulatory clearance, and clinical decision support are discussed.",
          ["FDA"], indications=["General"], category="Digital Health",
          plain="Software that does a medical job on its own — like an app that detects a heart problem — and is regulated as a medical device."),
    entry("Clinical Decision Support", "CDS",
          "Software prompts — alerts, reminders, order sets — that *help clinicians decide*, usually built right into the electronic health record.",
          "It delivers knowledge to clinicians at the point of care: drug-interaction alerts, dosing guidance, screening reminders, diagnostic suggestions. Embedded in the electronic health record, it can cut errors — but poorly tuned alerts cause 'alert fatigue.' Increasingly powered by AI and real-world evidence. You'll hear CDS in patient-safety, health-IT, and software-as-a-medical-device discussion.",
          ["ONC"], indications=["General"], category="Digital Health",
          plain="Software that gives doctors alerts and reminders — like flagging a dangerous drug combination — to help them make safer choices."),
    entry("HIPAA", "Health Insurance Portability and Accountability Act",
          "The 1996 US law that *protects health-data privacy* — its Privacy and Security Rules govern who may use protected health information.",
          "It sets national rules for safeguarding patients' protected health information, governing how providers, insurers, and their vendors may use and disclose it. The Privacy and Security Rules carry real penalties for breaches. It shapes everything from electronic health record access to what a telehealth app may store. You'll hear HIPAA invoked in any health-data, privacy, or digital health discussion.",
          ["HHS"], indications=["General"], category="Digital Health",
          plain="The US law that protects the privacy of your health information and limits who can see or share it."),
    entry("Protected Health Information", "PHI",
          "*Individually identifiable* health data — the category HIPAA protects, from diagnoses to billing records to the very fact of a visit.",
          "Any health data linked to an identifiable person — names, diagnoses, test results, even appointment dates. HIPAA governs its use; stripping identifiers ('de-identification') frees data for research and real-world evidence. Mishandling it — often from unsecured electronic health record systems — drives most healthcare data-breach penalties. You'll hear PHI in privacy, security, and data-sharing discussion across every digital health vendor.",
          ["HHS"], indications=["General"], category="Digital Health",
          plain="Any health data that can be tied to you — like your diagnoses or test results — that the law says must be kept private."),
    entry("Patient Portal", "",
          "The *patient-facing window* into the electronic health record — view results, message clinicians, book visits, refill prescriptions.",
          "The secure online front end to a provider's electronic health record, letting people read notes and labs, message care teams, and schedule visits. US rules now guarantee patients fast electronic access to their data, often via FHIR-based apps. Uptake varies with digital literacy. You'll hear patient portal in patient-engagement and interoperability discussion.",
          ["ONC"], indications=["General"], category="Digital Health",
          plain="A secure website or app where you can see your test results, message your doctor, and book appointments."),
    entry("Wearable", "",
          "A body-worn *sensor* — smartwatch, patch, ring — that streams health signals, feeding remote patient monitoring and digital biomarkers.",
          "Smartwatches, ECG patches, continuous glucose monitors, and rings passively capture physiological signals outside the clinic. They power remote patient monitoring and generate the digital biomarkers researchers increasingly use in trials. Data quality and clinical validation are the open questions. You'll hear wearable in connected-health, prevention, and decentralized trial discussion as consumer tech pushes into medicine.",
          ["FDA"], indications=["General"], category="Digital Health",
          plain="A device you wear, like a smartwatch, that tracks health data such as heart rate or steps."),
    entry("Real-World Data", "RWD",
          "The *raw data of everyday care* — electronic health records, claims, registries, wearables — that, once analyzed, becomes real-world evidence.",
          "Health information collected outside controlled trials: electronic health record entries, claims data, disease registries, and wearable streams. Analyzed, it becomes the real-world evidence the FDA increasingly accepts for label expansions and safety monitoring. Its messiness — missing fields, confounding — is the central challenge. You'll hear RWD across HEOR, regulatory, and digital health discussion.",
          ["FDA"], indications=["General"], category="Digital Health",
          plain="Health data gathered during everyday care — from records, claims, and devices — rather than from a formal clinical trial."),
    entry("Decentralized Trial", "DCT",
          "A clinical trial brought *to the patient* — telehealth visits, home nursing, e-consent, wearables — rather than requiring travel to a site.",
          "These shift study activities to participants' homes via telehealth, remote patient monitoring, electronic consent, and local labs, widening access and retention. Wearable devices and digital biomarkers supply continuous endpoints. The FDA has issued guidance encouraging the model, accelerated by the pandemic. You'll hear decentralized trial in clinical-operations and digital health discussion.",
          ["FDA"], indications=["General"], category="Digital Health",
          plain="A clinical trial run partly or fully at patients' homes — using telehealth, apps, and local labs — instead of only at trial sites."),
    entry("ePRO", "electronic Patient-Reported Outcome",
          "*Patient-reported* symptoms and outcomes captured electronically — on an app or device — rather than on paper at a clinic visit.",
          "It captures what patients say about their own symptoms, function, and quality of life directly through apps or handheld devices, replacing paper diaries. This improves data quality and timeliness in trials and routine care, and is a natural fit for decentralized trials, remote patient monitoring, and real-world data. You'll hear ePRO in trial-design and digital health discussion.",
          ["FDA"], indications=["General"], category="Digital Health",
          plain="Patients reporting their own symptoms and quality of life through an app or device during a study or their care."),
    entry("Digital Biomarker", "",
          "A *device-measured* physiological or behavioral signal — gait, sleep, heart rhythm — used like a lab biomarker to track disease or drug effect.",
          "Objective measures captured by sensors and apps — typing speed in Parkinson's, nocturnal cough, continuous glucose — that stand in for disease state or treatment response. Drawn from wearables and phones, they enable continuous endpoints in decentralized trials and remote patient monitoring. Validation against clinical outcomes is the hurdle. You'll hear digital biomarker in trial-innovation and digital health discussion.",
          ["FDA"], indications=["General"], category="Digital Health",
          plain="A health signal measured by a digital device — like gait from a phone or heart rhythm from a watch — used to track disease."),
]

# Batch 8 — clinical biostatistics & trial design (retro-lights Cohort Study,
# Case-Control Study, Confounding, Screening, Placebo, Hazard Ratio, etc.).
BATCH_8 = [
    entry("Randomized Controlled Trial", "RCT",
          "The *gold standard* of clinical evidence — patients assigned at random to treatment or control, so the groups differ only by chance, not bias.",
          "Random assignment breaks the link between who gets which treatment and their prognosis, defeating confounding by design — which is why it outranks the cohort study and case-control study in evidence. Add blinding and a placebo and you isolate a drug's true effect. It is the backbone of the phase 3 trial and the FDA approval that follows. You'll hear randomized controlled trial cited as the bar every new therapy must clear.",
          ["ICH E9"], indications=["General"], category="Clinical",
          plain="A study that splits people randomly into a treatment group and a comparison group, so you can trust the difference came from the treatment."),
    entry("Relative Risk", "RR",
          "How many *times* more likely an outcome is in one group versus another — intuitive, but it can exaggerate a tiny absolute difference.",
          "Divides the outcome rate in a treated or exposed group by the rate in the comparison group; 1 means no difference. The cohort study and randomized controlled trial measure it directly. A scary 'doubling' can hide a trivial absolute risk reduction when the baseline is tiny, so read it beside the number needed to treat. You'll hear relative risk in every results write-up and guideline debate.",
          ["NIH"], indications=["General"], category="Clinical",
          plain="How many times more likely something is in one group than another — a doubling of risk is a relative risk of two."),
    entry("Absolute Risk Reduction", "ARR",
          "The *plain-arithmetic* drop in risk — one group's event rate minus the other's — the honest counterweight to a flashy relative risk.",
          "Subtracts the treated group's event rate from the control's, giving the real-world benefit in percentage points rather than a ratio. Its inverse is the number needed to treat. A therapy can boast a large relative risk reduction while its absolute risk reduction stays tiny when the disease is rare. You'll hear absolute risk reduction demanded by skeptical clinicians and HEOR reviewers weighing whether a benefit justifies the price.",
          ["NIH"], indications=["General"], category="Clinical",
          plain="The simple difference in how often something happens between two groups — if 10% drops to 6%, that's a 4-point reduction."),
    entry("Odds Ratio", "OR",
          "The *odds* of an outcome in one group divided by the odds in another — the natural output of a case-control study and logistic models.",
          "Compares odds rather than probabilities; a case-control study reports it because such studies can't measure incidence directly. When an outcome is rare it approximates the relative risk, but for common outcomes it overstates the effect — a frequent source of headline confusion. It's quoted with a confidence interval to show precision. You'll hear odds ratio throughout epidemiology and genome-wide association results.",
          ["NIH"], indications=["General"], category="Clinical",
          plain="A way to compare the chances of an outcome between two groups using odds rather than plain percentages — common in look-back studies."),
    entry("Number Needed to Treat", "NNT",
          "How many patients must take a drug for *one* to benefit — the absolute risk reduction flipped into a single, clinic-ready number.",
          "The reciprocal of the absolute risk reduction: a 5% absolute risk reduction gives a number needed to treat of 20. Lower is better. It turns abstract statistics into a tangible sense of how much effort a benefit takes, cutting through an inflated relative risk. Its dark mirror is the number needed to harm. You'll hear number needed to treat when clinicians and HEOR teams judge whether a marginal benefit is worth it.",
          ["NIH"], indications=["General"], category="Clinical",
          plain="How many people need the treatment for one extra person to be helped — a value of 20 means treating twenty to help one."),
    entry("Confidence Interval", "CI",
          "The *range of plausible values* around a result — wide signals uncertainty, narrow signals precision, and crossing 'no effect' means non-significant.",
          "Usually a 95% interval: the band that would capture the true value 95% of the time across repeated studies. For a hazard ratio or odds ratio, an interval crossing 1 — or for a risk difference, crossing 0 — isn't statistically significant, echoing the p-value. Its width shrinks with sample size and statistical power. You'll hear confidence interval scrutinized in every trial readout and forest plot.",
          ["ICH E9"], indications=["General"], category="Clinical",
          plain="A range showing how sure we are of a result — narrow means a precise estimate, wide means we're guessing more."),
    entry("P-value", "",
          "The probability your result is a *fluke* — the chance of an effect this big if the drug truly did nothing; below 0.05 is the customary line.",
          "It's the probability of data at least this extreme if the null hypothesis — no real effect — held. The arbitrary 0.05 threshold defines statistical significance and accepts a 5% type I error rate, but a small p-value says nothing about effect size, so pair it with the confidence interval. Misuse and 'p-hacking' fueled the replication crisis. You'll hear p-value dissected wherever randomized controlled trial results and their credibility are weighed.",
          ["ICH E9"], indications=["General"], category="Clinical",
          plain="A number estimating how likely a result is just luck — the smaller it is, the less likely the finding came from chance alone."),
    entry("Statistical Power", "",
          "A study's *ability to detect a real effect* if one exists — too little, and a genuine benefit hides in the noise as a false negative.",
          "The probability of avoiding a type II error — of catching an effect that is truly present. By convention trials target 80–90% statistical power, which drives the sample-size calculation: rarer outcomes and smaller effects demand more patients. An underpowered study risks a falsely negative result and wasted patients. You'll hear statistical power argued over at the design stage of any randomized controlled trial.",
          ["ICH E9"], indications=["General"], category="Clinical",
          plain="A study's ability to spot a real effect when there is one — too small a study can miss a true benefit just by being underpowered."),
    entry("Type I Error", "",
          "A *false positive* — concluding a drug works when it doesn't — the mistake the 0.05 significance threshold is built to cap.",
          "Rejecting a true null hypothesis: declaring an effect that isn't real. Its rate is alpha, conventionally capped at 5% — the same line that marks a significant p-value. Testing many endpoints inflates it, which is why trials pre-specify a primary endpoint and adjust for multiplicity. Its counterpart is the type II error. You'll hear type I error invoked whenever a surprising subgroup finding gets waved off as a fluke.",
          ["ICH E9"], indications=["General"], category="Clinical",
          plain="A false alarm — deciding a treatment works when it really doesn't. The usual rules try hard to keep this mistake rare."),
    entry("Type II Error", "",
          "A *false negative* — missing a real drug effect — the failure that adequate statistical power and sample size guard against.",
          "Failing to reject a false null hypothesis: overlooking an effect that genuinely exists. Its rate is beta, and one minus beta is the statistical power. Underpowered trials — too few patients, or the wrong primary endpoint — are the usual cause, so sample size is set to keep beta low. Its mirror is the type I error. You'll hear type II error blamed when a promising therapy 'fails' a trial that was simply too small.",
          ["ICH E9"], indications=["General"], category="Clinical",
          plain="Missing something real — concluding a treatment doesn't work when it actually does, often because the study was too small to tell."),
    entry("Crossover Trial", "",
          "A design where each patient *receives both treatments in sequence* — serving as their own control, which sharpens the comparison and shrinks the sample.",
          "Each participant takes one therapy, then switches to the other after a washout period, so within-person comparisons cancel out individual variability — powerful for stable, chronic conditions. It needs fewer patients than a parallel randomized controlled trial but breaks down when effects carry over or the disease shifts. Blinding still applies. You'll hear crossover trial in early-phase and rare-disease study design.",
          ["ICH E9"], indications=["General"], category="Clinical",
          plain="A study where each person tries both the treatment and the comparison at different times, acting as their own basis for comparison."),
    entry("Stratification", "",
          "Splitting *enrollment into subgroups* — by stage, biomarker, or risk — then randomizing within each, so key factors stay balanced across the groups.",
          "Dividing participants by prognostic factors — disease stage, a biomarker, prior therapy — and randomizing within each layer guarantees those factors split evenly, stopping them from confounding the result. It also lets pre-planned subgroup analysis proceed honestly, and is set by the enrollment criteria. You'll hear stratification in trial-design and biomarker discussion, where a positive subgroup can rescue or sink a whole program.",
          ["ICH E9"], indications=["General"], category="Clinical",
          plain="Sorting study participants into groups by an important trait — like disease stage — before assigning treatment, so the groups stay comparable."),
    entry("Sensitivity", "",
          "A test's ability to *catch true cases* — high sensitivity means few sick people are missed, so a negative result is reassuring.",
          "The share of people with a disease whom a test correctly flags — its true-positive rate. A highly sensitive test produces few false negatives, so a clear result helps rule disease out, prized in screening. It trades off against specificity: dialing one up often drags the other down. Combined with disease prevalence, it shapes the negative predictive value. You'll hear sensitivity quoted for every diagnostic and screening tool.",
          ["NIH MedlinePlus"], indications=["General"], category="Diagnostics",
          plain="How good a test is at catching people who really have a disease — a very sensitive test rarely misses a true case."),
    entry("Specificity", "",
          "A test's ability to *clear the truly healthy* — high specificity means few false alarms, so a positive result is more believable.",
          "The share of disease-free people a test correctly clears — its true-negative rate. High specificity means few false positives, so a positive result is more trustworthy and confirmatory testing leans on it. It trades against sensitivity. With disease prevalence it sets the positive predictive value — which is why even a specific test throws many false alarms when a disease is rare. You'll hear specificity beside sensitivity in any diagnostic's performance claims.",
          ["NIH MedlinePlus"], indications=["General"], category="Diagnostics",
          plain="How good a test is at correctly clearing people who don't have a disease — a very specific test rarely raises a false alarm."),
    entry("Positive Predictive Value", "PPV",
          "If your test reads *positive*, the chance you truly have the disease — and, unlike specificity, it sinks when the condition is rare.",
          "The probability that a positive result is a true positive. Unlike sensitivity and specificity, it swings with disease prevalence: in a rare disease even an excellent test produces many false positives, dragging the positive predictive value down — the core argument against mass screening for uncommon conditions. Its mirror is the negative predictive value. You'll hear positive predictive value whenever a screening program's real-world usefulness, not just its lab accuracy, is debated.",
          ["NIH MedlinePlus"], indications=["General"], category="Diagnostics",
          plain="When a test comes back positive, how likely it is you actually have the disease — which depends heavily on how common it is."),
    entry("Negative Predictive Value", "NPV",
          "If your test reads *negative*, the chance you're truly disease-free — usually high when the disease is rare, reassuring after a clear result.",
          "The probability that a negative result is a true negative. Like the positive predictive value it depends on disease prevalence, but in the opposite direction: when a disease is rare a negative result is almost always right, so the negative predictive value runs high. It rises with a test's sensitivity. You'll hear negative predictive value cited when clinicians ask how confidently a negative test rules a condition out.",
          ["NIH MedlinePlus"], indications=["General"], category="Diagnostics",
          plain="When a test comes back negative, how likely it is you really don't have the disease — usually very high for rare conditions."),
]

BATCHES: dict[int, list] = {
    1: BATCH_1,
    2: BATCH_2,
    3: BATCH_3,
    4: BATCH_4,
    5: BATCH_5,
    6: BATCH_6,
    7: BATCH_7,
    8: BATCH_8,
}


def merge(batches_to_run, dry_run=False):
    existing = json.loads(GLOSSARY.read_text())
    existing_names = {t["term"].lower() for t in existing}

    new_entries = []
    for n in batches_to_run:
        batch = BATCHES.get(n)
        if batch is None:
            print(f"warning: batch {n} not found, skipping")
            continue
        for e in batch:
            key = e["term"].lower()
            if key in existing_names:
                print(f"skip: {e['term']} already exists")
                continue
            new_entries.append(e)
            existing_names.add(key)

    if dry_run:
        print(f"would merge {len(new_entries)} new entries; total would be {len(existing) + len(new_entries)}")
        return

    combined = existing + new_entries
    combined.sort(key=lambda t: (t["letter"], t["term"].lower()))
    GLOSSARY.write_text(json.dumps(combined, ensure_ascii=False, indent=2) + "\n")
    print(f"merged {len(new_entries)} new entries; total {len(combined)}")


def parse_args():
    p = argparse.ArgumentParser()
    p.add_argument("--batches", default=",".join(str(n) for n in BATCHES),
                   help="comma-separated batch numbers to run (default: all)")
    p.add_argument("--dry-run", action="store_true", help="preview without writing")
    return p.parse_args()


if __name__ == "__main__":
    args = parse_args()
    nums = [int(x) for x in args.batches.split(",") if x.strip()]
    merge(nums, dry_run=args.dry_run)
